import test from 'node:test';
import assert from 'node:assert/strict';
import { buildDailyEditorialPlan, registerPublishedEditorial, selectLatestCompletedDate } from '../src/editorial/daily-editorial-plan.js';
import { buildVerifiedProductionLibrary } from '../src/library/production-library.js';
import { createDefaultEditorialMemory } from '../src/library/retrieval.js';
const now = '2026-10-06T18:00:00+09:00';
const candidate = (overrides = {}) => ({ candidateId: 'candidate:new', topic: 'Sovereign AI 운영 통제', companyIds: ['company:microsoft'], themeIds: ['theme:agent-security'], eventId: 'event:microsoft-sovereign-ai-2026-10-05', continuationOfEventId: null, sourceRefs: ['https://www.microsoft.com/en-us/microsoft-cloud/blog/general/2026/10/05/sovereign-ai-accelerate-innovation-with-control-and-choice/'], importanceReason: '규제 산업의 AI 운영 통제를 구체화', noveltyReason: '새 공식 white paper 공개', marketRelevance: '클라우드·AI 인프라 도입 조건 변화', sourceQuality: 'OFFICIAL', crossVerification: ['Microsoft official publication'], lead: true, depth: { whatHappened: 'Microsoft와 NVIDIA가 소버린 AI 원칙을 공개', whyImportant: '민감 데이터와 모델 운영 통제가 도입 조건으로 부상', whatChanged: '데이터 위치 중심 논의가 모델·에이전트·운영 통제로 확장', marketMeaning: '클라우드·가속기·보안 스택의 결합 경쟁 심화', whatNext: '실제 고객 도입과 규제 적용 범위 확인' }, ...overrides });
test('DailyEditorialPlan records selected, deferred and rejected candidates without scores', () => { const library = buildVerifiedProductionLibrary(now).store; const duplicateEvent = library.records.find(item => item.canonicalId === 'event:openai-dots-2026-09-29'); const result = buildDailyEditorialPlan({ category: 'AI_INTELLIGENCE', issueDate: '2026-10-05', library, memory: createDefaultEditorialMemory(now), generatedAt: now, candidates: [candidate(), candidate({ candidateId: 'candidate:defer', eventId: 'event:later', recommendedTreatment: 'DEFER', lead: false }), candidate({ candidateId: 'candidate:duplicate', eventId: duplicateEvent.canonicalId, sourceRefs: duplicateEvent.sourceRefs, lead: false })] }); assert.equal(result.plan.selected.length, 1); assert.equal(result.plan.deferred.length, 1); assert.equal(result.plan.rejected.length, 1); assert.equal(result.plan.rejected[0]?.coverageState, 'DUPLICATE'); assert.equal('score' in result.plan.candidates[0], false); assert.equal(result.plan.reviewState, 'APPROVAL_REQUIRED'); });
test('follow-up preserves prior coverage and uses FOLLOW_UP treatment', () => { const library = buildVerifiedProductionLibrary(now).store; const result = buildDailyEditorialPlan({ category: 'AI_INTELLIGENCE', issueDate: '2026-10-05', library, memory: createDefaultEditorialMemory(now), generatedAt: now, candidates: [candidate({ continuationOfEventId: 'event:openai-dots-2026-09-29' })] }); assert.equal(result.plan.selected[0]?.coverageState, 'FOLLOW_UP'); assert.equal(result.plan.selected[0]?.recommendedTreatment, 'FOLLOW_UP'); assert.ok(result.plan.selected[0]?.priorCoverage.relatedRecordIds.length); });
test('content depth gate sends incomplete copy to MODIFY', () => { const result = buildDailyEditorialPlan({ category: 'US_MARKET', issueDate: '2026-10-05', library: buildVerifiedProductionLibrary(now).store, memory: createDefaultEditorialMemory(now), generatedAt: now, candidates: [candidate({ depth: { ...candidate().depth, whatNext: '' } })] }); assert.equal(result.plan.contentDepthGate, 'FAIL'); assert.equal(result.plan.reviewState, 'MODIFY'); });
test('latest completed date is category independent and excludes holidays', () => { assert.equal(selectLatestCompletedDate({ category: 'US_MARKET', availableDates: ['2026-10-02', '2026-10-05', '2026-10-06'], completedThrough: '2026-10-05' }), '2026-10-05'); assert.equal(selectLatestCompletedDate({ category: 'KOREA_MARKET', availableDates: ['2026-10-02', '2026-10-05', '2026-10-06'], completedThrough: '2026-10-06', holidays: ['2026-10-05'] }), '2026-10-06'); });
test('post-publish registration is blocked before human approval', () => { const result = buildDailyEditorialPlan({ category: 'AI_INTELLIGENCE', issueDate: '2026-10-05', library: buildVerifiedProductionLibrary(now).store, memory: createDefaultEditorialMemory(now), generatedAt: now, candidates: [candidate()] }); assert.throws(() => registerPublishedEditorial({ plan: result.plan, publicPostUrl: 'https://motusnova.blogspot.com/2026/10/example.html', publishedAt: now }), /human APPROVED/); });
test('post-publish registration prepares weekly and review-required memory without fake search metrics', () => { const result = buildDailyEditorialPlan({ category: 'AI_INTELLIGENCE', issueDate: '2026-10-05', library: buildVerifiedProductionLibrary(now).store, memory: createDefaultEditorialMemory(now), generatedAt: now, candidates: [candidate()] }); const plan = { ...result.plan, reviewState: 'APPROVED' }; const registered = registerPublishedEditorial({ plan, publicPostUrl: 'https://motusnova.blogspot.com/2026/10/example.html', publishedAt: now }); assert.equal(registered.weeklyFeed.issueDate, '2026-10-05'); assert.equal(registered.searchRegistration.indexed, false); assert.equal(registered.memoryCandidates[0]?.reviewState, 'REVIEW_REQUIRED'); });
